// The types of Cauthy's public API (openapi/cauthy.yaml) and of the auth-bff
// protocol (openapi/auth-bff.yaml), generated by openapi-typescript into
// cauthy.d.ts and auth-bff.d.ts. Types only: import them with `import type`.
import type { components as CauthyComponents, operations as CauthyOperations, paths as CauthyPaths } from './cauthy.js'
import type { components as AuthBffComponents, paths as AuthBffPaths } from './auth-bff.js'

export type { AuthBffComponents, AuthBffPaths, CauthyComponents, CauthyOperations, CauthyPaths }

/** A schema of Cauthy's public API by name: `CauthySchema<'OAuthUserInfo'>`. */
export type CauthySchema<Name extends keyof CauthyComponents['schemas']> = CauthyComponents['schemas'][Name]

/** `{"data": T}`: how Cauthy answers with one resource. */
export interface CauthyData<T> {
  data: T
}

/** `{"data": T[], "total_count": n}`: how Cauthy answers with a list. */
export interface CauthyList<T> {
  data: T[]
  total_count: number
}

/** The auth-bff protocol version these types describe (cauthy-sdk-spec's VERSION). */
export type ProtocolVersion = 1
